#' Categorical Alluvial Flows (Python Core)
#'
#' 
#' @param data .
#' @param vars .
#' @param excl .
#' @param showFlowTable .
#' @param showCategories .
#' @param showPlot .
#' @param interactive .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$flows} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$categories} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$flowPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$flows$asDF}
#'
#' \code{as.data.frame(results$flows)}
#'
#' @export
pyalluvial <- function(
    data,
    vars = NULL,
    excl = FALSE,
    showFlowTable = FALSE,
    showCategories = FALSE,
    showPlot = TRUE,
    interactive = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyalluvial requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyalluvialOptions$new(
        vars = vars,
        excl = excl,
        showFlowTable = showFlowTable,
        showCategories = showCategories,
        showPlot = showPlot,
        interactive = interactive,
        showConsole = showConsole)

    analysis <- pyalluvialClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

